input.sparql:
SELECT ?z ?zname ?p ?s WHERE {
  ?z a brick:Zone ; rdfs:label ?zname .
  FILTER(?zname IN ("Perimeter_bot_ZN_2", "DataCenter_mid_ZN_6"))
  OPTIONAL { ?z brick:hasPoint ?p ; ?p ref:hasTimeseriesId ?s }
}

SELECT ?r ?rname ?p ?s WHERE {
  ?r a brick:Room .
  FILTER(rdfs:label(?r) IN ("Perimeter_bot_ZN_2", "DataCenter_mid_ZN_6"))
}

SELECT ?z ?zname WHERE {
  ?z a brick:Zone ; rdfs:label ?zname .
  FILTER(?zname IN ("Perimeter_bot_ZN_2", "DataCenter_mid_ZN_6"))
}

SELECT ?z ?zname (str(?t) AS ?type) WHERE {
  ?z rdfs:label ?zname .
  FILTER(CONTAINS(LCASE(?zname), "ZN_") || CONTAINS(LCASE(?zname), "Perimeter") || CONTAINS(LCASE(?zname), "DataCenter"))
  OPTIONAL { ?z a ?t . }
}

SELECT ?z ?t WHERE {
  ?z rdfs:label "DataCenter_mid_ZN_6" .
  ?z a ?t .
  FILTER NOT EXISTS { ?z a brick:Room . }
}
